package com.example.rokidgeminisecretary;
import android.content.*;import org.json.*;import java.io.*;import java.util.*;
/** Bounded suggestions only. No automatic deletion or merging. */
final class DuplicateReview {
 static JSONArray pairs(Context c)throws Exception{JSONArray out=new JSONArray(),notes=PersonalNotes.list(c);for(int i=0;i<notes.length();i++)for(int j=i+1;j<notes.length()&&out.length()<30;j++){JSONObject a=notes.getJSONObject(i),b=notes.getJSONObject(j);double score=ExperiencePolicy.similarity(a.getString("text"),b.getString("text"));if(score>=.8){JSONObject row=new JSONObject().put("type","note").put("keepId",a.getString("id")).put("removeId",b.getString("id")).put("keepText",a.getString("text")).put("removeText",b.getString("text")).put("keepRevision",a.optInt("revision",1)).put("removeRevision",b.optInt("revision",1)).put("similarity",score);row.put("revision",ReviewStore.hash(row));out.put(row);}}File[] photos=RecorderPhotoStore.root(c).listFiles((d,n)->n.matches("[0-9]{13}-[a-f0-9-]{36}\\.gcm"));if(photos==null)throw new IOException("写真一覧を確認できません");Arrays.sort(photos,(a,b)->b.getName().compareTo(a.getName()));HashMap<String,File> seen=new HashMap<>();for(int i=0;i<Math.min(200,photos.length)&&out.length()<50;i++){File photo=photos[i];JSONObject receipt;try{receipt=VerifiedStorage.receipt(photo);}catch(Exception unavailable){continue;}String sha=receipt.optString("sha");if(!sha.matches("[a-f0-9]{64}"))continue;File keeper=seen.get(sha);if(keeper==null){seen.put(sha,photo);continue;}JSONObject row=new JSONObject().put("type","photo").put("keepId",keeper.getName().replace(".gcm","")).put("removeId",photo.getName().replace(".gcm","")).put("sha",sha).put("similarity",1);row.put("revision",ReviewStore.hash(row));out.put(row);}return out;}
 static JSONObject cleanup(Context c,JSONObject in)throws Exception{String lease=MaintenanceLease.acquire(c,"cleanup");boolean success=false;try{String type=in.getString("type");JSONObject chosen=null;JSONArray candidates=pairs(c);for(int i=0;i<candidates.length();i++){JSONObject row=candidates.getJSONObject(i);if(type.equals(row.optString("type"))&&in.getString("keepId").equals(row.optString("keepId"))&&in.getString("removeId").equals(row.optString("removeId"))&&in.getString("revision").equals(row.optString("revision")))chosen=row;}if(chosen==null)throw new IOException("候補が変わりました。両方を確認し直してください");if(type.equals("note"))synchronized(PersonalNotes.class){JSONObject keep=PersonalNotes.detail(c,chosen.getString("keepId")),remove=PersonalNotes.detail(c,chosen.getString("removeId"));if(keep.optLong("deletedAt")>0||remove.optLong("deletedAt")>0||keep.optInt("revision",1)!=chosen.getInt("keepRevision")||remove.optInt("revision",1)!=chosen.getInt("removeRevision"))throw new IOException("メモが変わりました");PersonalNotes.delete(c,remove.getString("id"));success=true;return new JSONObject().put("message","選んだメモだけごみ箱へ移動しました").put("note",PersonalNotes.detail(c,remove.getString("id")));}else if(type.equals("photo"))synchronized(RecorderPhotoStore.class){File keep=new File(RecorderPhotoStore.root(c),chosen.getString("keepId")+".gcm"),remove=new File(RecorderPhotoStore.root(c),chosen.getString("removeId")+".gcm");String sha=chosen.getString("sha");if(!keep.isFile()||!remove.isFile()||!RecorderPhotoStore.hash(RecorderPhotoStore.read(keep)).equals(sha)||!RecorderPhotoStore.hash(RecorderPhotoStore.read(remove)).equals(sha))throw new IOException("写真の実データが一致しません。削除していません");RecorderPhotoStore.delete(c,remove);success=true;return new JSONObject().put("message","選んだスマホ内の写真だけ完全削除しました。残す写真とグラス・ギャラリーは変更していません");}else throw new IOException("種類が不正です");}finally{MaintenanceLease.finish(c,lease,success?"COMPLETED":"FAILED");}}
 private DuplicateReview(){}
}
